with account_totals as (select account_id, round((100 * sum(case when txn_type = 'CREDIT' then 1 else 0 end)) / count(*), 1) as pct_credit, max(amount) - min(amount) as amount_range from transactions group by account_id) select accounts.id, accounts.opened_date, accounts.account_type, account_totals.pct_credit, account_totals.amount_range from accounts inner join account_totals on accounts.id = account_totals.account_id;
